<section class="page-heading"><span class="eyebrow">A MORE CONSIDERED CHOICE</span><h1><?= e($title) ?></h1><p>Compare up to four available homes.</p></section><div class="page-main"><?php if (!$data['properties']): ?><div class="empty"><h3>Your shortlist starts with a home.</h3><p>Select Compare on any property card.</p><a href="/properties" class="button">Explore the collection</a></div><?php else: ?><div class="table-wrap"><table class="compare-table"><tr><th>Property</th><?php foreach ($data['properties'] as $p): ?><td><a href="/property?id=<?= $p['id'] ?>"><img src="<?= e($p['cover_url'] ?: '/assets/favicon.svg') ?>" alt="Illustrative home"><h3><?= e($p['title']) ?></h3></a></td><?php endforeach ?></tr><?php foreach (['price_minor'=>'Price (USD)','purpose'=>'Purpose','property_type'=>'Type','bedrooms'=>'Bedrooms','bathrooms'=>'Bathrooms','floor_area'=>'Floor area','area_unit'=>'Unit','city'=>'City','status'=>'Status'] as $k=>$label): ?><tr><th><?= $label ?></th><?php foreach ($data['properties'] as $p): ?><td><?= $k==='price_minor'?money($p[$k]):e(ucfirst(str_replace('_',' ',$p[$k]))) ?></td><?php endforeach ?></tr><?php endforeach ?></table></div><?php endif ?></div>
